contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with parameters that drive the call
    function run(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public payable {
        require(true);

        // Read the depositorAccount public getter before attempting the call
        address depositor = c.depositorAccount();

        // Attempt the state-changing call and capture whether it reverted
        bool reverted;
        try c.setL1BlockValues(
            _number,
            _timestamp,
            _basefee,
            _hash,
            _sequenceNumber,
            _batcherHash,
            _l1FeeOverhead,
            _l1FeeScalar
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The general rule: the call succeeds (not reverted) iff the depositorAccount equals this contract's address
        assert(reverted == (depositor != address(this)));
    }

    receive() external payable {}
}
